create extension if not exists "pgcrypto";
create table if not exists stores(id uuid primary key default gen_random_uuid(),owner_id uuid references auth.users(id) not null,store_name text not null,phone text,logo_url text,created_at timestamptz default now());
create table if not exists customers(id uuid primary key default gen_random_uuid(),store_id uuid references stores(id) on delete cascade not null,name text not null,phone text not null,email_or_id text,address text,notes text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists services(id uuid primary key default gen_random_uuid(),store_id uuid references stores(id) on delete cascade not null,name text not null,description text,is_active boolean default true,created_at timestamptz default now());
create table if not exists packages(id uuid primary key default gen_random_uuid(),store_id uuid references stores(id) on delete cascade not null,service_id uuid references services(id) on delete cascade,package_name text not null,price numeric(12,2) default 0,duration_days int default 30,is_active boolean default true,created_at timestamptz default now());
create table if not exists orders(id uuid primary key default gen_random_uuid(),store_id uuid references stores(id) on delete cascade not null,customer_id uuid references customers(id) on delete cascade not null,service_id uuid references services(id) on delete restrict not null,package_id uuid references packages(id) on delete set null,price numeric(12,2) default 0,paid_amount numeric(12,2) default 0,payment_status text not null check(payment_status in('مدفوع','غير مدفوع','جزئي')),start_date date,end_date date,notes text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists payments(id uuid primary key default gen_random_uuid(),store_id uuid references stores(id) on delete cascade not null,order_id uuid references orders(id) on delete cascade not null,amount numeric(12,2) not null,payment_method text default 'نقدًا',payment_date date default current_date,notes text,created_at timestamptz default now());
alter table stores enable row level security;alter table customers enable row level security;alter table services enable row level security;alter table packages enable row level security;alter table orders enable row level security;alter table payments enable row level security;
create policy "stores_owner_all" on stores for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "customers_owner_all" on customers for all using(exists(select 1 from stores where stores.id=customers.store_id and stores.owner_id=auth.uid())) with check(exists(select 1 from stores where stores.id=customers.store_id and stores.owner_id=auth.uid()));
create policy "services_owner_all" on services for all using(exists(select 1 from stores where stores.id=services.store_id and stores.owner_id=auth.uid())) with check(exists(select 1 from stores where stores.id=services.store_id and stores.owner_id=auth.uid()));
create policy "packages_owner_all" on packages for all using(exists(select 1 from stores where stores.id=packages.store_id and stores.owner_id=auth.uid())) with check(exists(select 1 from stores where stores.id=packages.store_id and stores.owner_id=auth.uid()));
create policy "orders_owner_all" on orders for all using(exists(select 1 from stores where stores.id=orders.store_id and stores.owner_id=auth.uid())) with check(exists(select 1 from stores where stores.id=orders.store_id and stores.owner_id=auth.uid()));
create policy "payments_owner_all" on payments for all using(exists(select 1 from stores where stores.id=payments.store_id and stores.owner_id=auth.uid())) with check(exists(select 1 from stores where stores.id=payments.store_id and stores.owner_id=auth.uid()));
